INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demeter', 'In this revolutionary platformer, you will find yourself for the first time ever solving puzzles, fighting enemies and exploring a brand new world in your own living room. The game uses mixed reality to create levels and challenges in real time that adapt to the environment you are in. Climb, jump, fly and run using your walls - and your furniture! - in a way you have never experienced before.' FROM games WHERE igdb_id = 280059 ON CONFLICT (game_id, language_code) DO NOTHING;
