INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pepe Chatters', 'Pepe Chatters is an exciting game in which the player has to help the cute frog Pepe solve riddles and puzzles to save his friends from the clutches of an evil sorcerer. With the help of clever jokes and a vivid sense of humor, Pepe will explore different levels, meet interesting characters and collect unique items to solve problems. Immerse yourself in Pepe''s magical world and help him bring peace and tranquility back to his home!' FROM games WHERE igdb_id = 287356 ON CONFLICT (game_id, language_code) DO NOTHING;
