INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fear Calibration', 'Who are you? What time is it? How long have you been in this place? In this horror-puzzle escape room, uncover the dark secrets hidden within the shadows as you solve your way through the empty classrooms of your school–or what seems to be of it. Do you really think you can escape this madness?' FROM games WHERE igdb_id = 303072 ON CONFLICT (game_id, language_code) DO NOTHING;
