INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turlock Holmes', 'A detective narrative puzzler without pre-set options! Raise your questions at will, and an AI-host will answer only with ''yes'' or ''no.'' Drive the investigation with your curiosity; the path to solving the mystery lies in questions you ask. Can you dig out the truth through your questions?' FROM games WHERE igdb_id = 286086 ON CONFLICT (game_id, language_code) DO NOTHING;
