INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('papas-paleteria-to-go', 290074, '2024-03-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8uk6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scqzqr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa''s Paleteria To Go!', 'After winning a priceless pendant at the grand opening of Papa''s Paleteria, excitement turns to chaos when Toby the Sea Lion dashes off with your cherished prize! Papa Louie sets off in pursuit, and leaves you to run the new shop instead! Now it''s up to you to helm the operation, crafting delectable paletas and ice pops for everyone visiting the seaside town of San Fresco. Pour a variety of purees, creams, and chunky fillings into paleta molds, and send them to the deep freeze for a quick chill. Decorate the frozen treats with a variety of dips, drizzles, and toppings before serving them to your picky customers. Work your way through the holidays as you serve seasonal ice pops, unlock new ingredients, and earn Daily Specials featuring delicious paleta recipes that will keep your customers coming back for more.' FROM games WHERE igdb_id = 290074 ON CONFLICT (game_id, language_code) DO NOTHING;
