INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Polity', 'Polity is a casual cross-platform MMORPG set in a dynamic, player-driven world. Players have the opportunity to govern colonies, join other colonies, explore the world, uncover the lore or master diverse skills such as farming, forestry, fishing etc. With a wide variety of features such as quests, achievements, puzzles, mini-games, and crafting, along with extensive customization options, Polity encourages players to forge their own path and create their own unique journey within its expansive virtual realm.' FROM games WHERE igdb_id = 149228 ON CONFLICT (game_id, language_code) DO NOTHING;
