INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gemz', 'Immerse yourself in the fast-paced world of Gemz, where your shield stands as the last line of defense against advancing gemstones. Use precise control to block and smash gems, collecting powerups, coins, and facing off against mini-bosses along the way. As time ticks away, the gems intensify in speed, testing your reflexes and strategic thinking. Combine powerups for ultimate survival as you strive for the highest score and become the ultimate Gemz master!' FROM games WHERE igdb_id = 299501 ON CONFLICT (game_id, language_code) DO NOTHING;
