INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remute: Remute 3D', 'Are you ready to dive into peak ''multimedia''? With TIME magazine''s ''1993 product of the year''? Wanna play with the... 3DO?! After just releasing There Is Hope for the Atari Jaguar this year, Remute goes even more niche and already comes up with his next interactive music album Remute 3D exclusively for the 3DO.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 321801 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
