INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aurans', 'Aurans is a kinetic visual novel, meaning it is linear and with no choices. It is a story about coming of age, learning to believe in yourself, and finding out what really matters to you. Everything is fully hand drawn, and is the first visual novel project of Pixelsplosion Studios.' FROM games WHERE igdb_id = 289672 ON CONFLICT (game_id, language_code) DO NOTHING;
