INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warfront Tactics: Battlefield Chronicles Battle Simulator', 'Unleash the commander within in Warfront Tactics - Battlefield Chronicles Battle Simulator, a captivating physics-based strategy game that thrusts you into the heart of epic warfare. Strategically allocate your resources, craft a formidable army, and outmaneuver your opponents in intense battles governed by realistic physics. Witness the chaos and spectacle of combat as your meticulously planned strategies unfold on the battlefield. Every decision carries weight, every encounter presents a challenge, and every victory is hard-won.' FROM games WHERE igdb_id = 304271 ON CONFLICT (game_id, language_code) DO NOTHING;
