INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abandoned City', 'Welcome to the abandoned city. All that''s left in this city are zombies, and maybe they''re interested in you. At the moment you are isolated, sure to die, but you have to hold on for as long as you can. Do you happen to know if someone will see your desperate uprising and rescue you..' FROM games WHERE igdb_id = 316439 ON CONFLICT (game_id, language_code) DO NOTHING;
